package {{PAQUETE}}

import okhttp3.OkHttpClient
import okhttp3.Protocol
import okhttp3.Request
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.IOException
import java.net.InetSocketAddress
import java.net.Proxy

class TraceEventListenerTest {
    private val call = OkHttpClient().newCall(Request.Builder().url("https://api.test/items/42").build())

    @Test
    fun completedCallTracesQueueConnectionAndTtfbInsideHttp() {
        val tracer = RecordingTracer()
        val listener = TraceEventListener(call, tracer)
        val address = InetSocketAddress.createUnresolved("api.test", 443)
        listener.callStart(call)
        listener.dnsStart(call, "api.test")
        listener.connectStart(call, address, Proxy.NO_PROXY)
        listener.connectEnd(call, address, Proxy.NO_PROXY, Protocol.HTTP_2)
        listener.requestHeadersEnd(call, call.request())
        listener.responseHeadersStart(call)
        listener.callEnd(call)
        assertEquals(
            listOf(
                "beginAsync HTTP GET /items/{id}",
                "beginAsync QUEUE GET /items/{id}",
                "endAsync QUEUE GET /items/{id}",
                "beginAsync CONN GET /items/{id}",
                "endAsync CONN GET /items/{id}",
                "beginAsync TTFB GET /items/{id}",
                "endAsync TTFB GET /items/{id}",
                "endAsync HTTP GET /items/{id}"
            ),
            tracer.events
        )
    }

    @Test
    fun failedCallClosesTheOpenSections() {
        val tracer = RecordingTracer()
        val listener = TraceEventListener(call, tracer)
        listener.callStart(call)
        listener.requestHeadersEnd(call, call.request())
        listener.callFailed(call, IOException("offline"))
        val opened = tracer.events.count { it.startsWith("beginAsync") }
        val closed = tracer.events.count { it.startsWith("endAsync") }
        assertEquals(opened, closed)
    }

    @Test
    fun queryBecomesAShortTagSoOtherParametersAreNotDuplicates() {
        fun name(url: String) = HttpSectionName.endpoint(Request.Builder().url(url).build())
        val page1 = name("https://api.test/items?page=1")
        assertTrue(page1, page1.matches(Regex("GET /items #[0-9a-f]{4}")))
        assertNotEquals(page1, name("https://api.test/items?page=2"))
        assertEquals(page1, name("https://api.test/items?page=1"))
        assertEquals("GET /items", name("https://api.test/items"))
    }

    @Test
    fun sanitizeReplacesNumericIdsAndUuids() {
        assertEquals("/a/{id}/b/{id}", HttpSectionName.sanitize("/a/123/b/123e4567-e89b-12d3-a456-426614174000"))
    }

    @Test
    fun sanitizeReplacesSegmentsWithSixOrMoreDigitsEvenWithHyphensOrDots() {
        assertEquals(
            "/clientes/{id}/cuentas/{id}",
            HttpSectionName.sanitize("/clientes/1234-5678-90/cuentas/00-123-456789-0")
        )
        assertEquals("/clientes/{id}", HttpSectionName.sanitize("/clientes/AB-123.456.789"))
        assertEquals("/pagos/{id}/detalle", HttpSectionName.sanitize("/pagos/ORD-2026-000123/detalle"))
    }

    @Test
    fun sanitizeKeepsShortVersionsAndPages() {
        assertEquals("/v3.7/items/pagina-12", HttpSectionName.sanitize("/v3.7/items/pagina-12"))
        assertEquals("/api/v2/lotes/a1b2c3", HttpSectionName.sanitize("/api/v2/lotes/a1b2c3"))
    }

    @Test
    fun aLongPathIsShortenedFromTheLeftAndFitsInASectionName() {
        val gateway = "/gateway/" + "segmento-largo/".repeat(12)
        fun name(path: String) = HttpSectionName.endpoint(Request.Builder().url("https://api.test$path").build())
        val movements = name(gateway + "clientes/42/movimientos?page=1")
        assertTrue(movements, "QUEUE $movements".length < MAX_SECTION_NAME)
        assertTrue(movements, movements.matches(Regex("GET ~[0-9a-f]{4}/.*clientes/\\{id}/movimientos #[0-9a-f]{4}")))
        // the same beginning and another end: still two endpoints
        assertNotEquals(movements, name(gateway + "clientes/42/saldos?page=1"))
        // the same end behind another prefix: the hash of what was removed keeps them apart
        assertNotEquals(movements, name("/otro" + gateway + "clientes/42/movimientos?page=1"))
        // the same endpoint with another id keeps its name
        assertEquals(movements, name(gateway + "clientes/43/movimientos?page=1"))
    }

    @Test
    fun aPathThatFitsKeepsItsNameAndAHugeSegmentIsStillCapped() {
        assertEquals("GET /items/{id} #0000", HttpSectionName.shorten("GET", "/items/{id}", " #0000"))
        val exact = "/" + "a".repeat(HttpSectionName.MAX_ENDPOINT_NAME - "GET ".length - 1)
        assertEquals("GET $exact", HttpSectionName.shorten("GET", exact, ""))
        val huge = HttpSectionName.shorten("GET", "/" + "b".repeat(300), " #1a2b")
        assertEquals(HttpSectionName.MAX_ENDPOINT_NAME, huge.length)
        assertTrue(huge, huge.startsWith("GET ~") && huge.endsWith("b #1a2b"))
    }

    private class RecordingTracer : SectionTracer {
        val events = mutableListOf<String>()

        override fun beginSection(name: String) {
            events += "begin $name"
        }

        override fun endSection() {
            events += "end"
        }

        override fun beginAsyncSection(name: String, cookie: Int) {
            events += "beginAsync $name"
        }

        override fun endAsyncSection(name: String, cookie: Int) {
            events += "endAsync $name"
        }
    }
}
